'use strict';
const $ = (s) => document.querySelector(s);
const $$ = (s) => [...document.querySelectorAll(s)];
const money = n => `₹${n.toLocaleString('en-IN')}`;
const colours = [ {id:'denim',name:'Blue jean day',hex:'#6686a0',light:'#95aabd'}, {id:'rose',name:'Rosy outlook',hex:'#c98791',light:'#e2b4af'}, {id:'sage',name:'Garden green',hex:'#839679',light:'#b4bea0'}, {id:'butter',name:'Butter together',hex:'#c3a96b',light:'#e0cd9b'}, {id:'ink',name:'After hours',hex:'#4e5a61',light:'#83939b'} ];
const bags = [
 {id:'tote',name:'The Everyday Tote',tag:'THE CLOSET CLASSIC',category:'everyday',price:499,bg:'#e7e9dd',colour:'denim',pattern:'plain',description:'For big plans & all the little things.',fabric:'Lovely in denim or sturdy cotton'},
 {id:'mini',name:'The Little Mood',tag:'SMALL BAG, BIG ENERGY',category:'mini',price:399,bg:'#f0dce0',colour:'rose',pattern:'patch',description:'Phone, keys, a little main character.',fabric:'Made for your favourite fabric mix'},
 {id:'shoulder',active:false,name:'The Daydreamer',tag:'YOUR NEW EVERYWHERE BAG',category:'shoulder',price:599,bg:'#e7e9cf',colour:'sage',pattern:'plain',description:'An over-the-shoulder kind of love.',fabric:'Try cotton, corduroy or sturdy blends'},
 {id:'bucket',active:false,name:'The Bucket List',tag:'A LITTLE DIFFERENT',category:'everyday',price:549,bg:'#eee2cc',colour:'butter',pattern:'stripe',description:'Room for all your beautiful chaos.',fabric:'Good with denim & heavier cotton'}
];
let svgId=0, step=0, selectedColour='denim', photoURL=null, isSaving=false;
const STORAGE_KEY='rebag-state-v2', R=globalThis.RebagRewards, D=globalThis.RebagDesign;
let storageAvailable=true, state=R.empty(), saved=state.makes;
function readState(){const current=localStorage.getItem(STORAGE_KEY);if(current)return R.parse(current);const legacy=JSON.parse(localStorage.getItem('rebag-makes-v1')||'[]');return R.parse(null,Array.isArray(legacy)?legacy.filter(validMake):[]);}
try { state=readState();saved=state.makes; } catch { storageAvailable=false; }
async function transact(change){
 const commit=()=>{const next=readState();change(next);localStorage.setItem(STORAGE_KEY,JSON.stringify(next));state=next;saved=state.makes;storageAvailable=true;updateCount();};
 if(navigator.locks) await navigator.locks.request('rebag-rewards-wallet',commit);else commit();
}
function validMake(m){return m && typeof m.id==='string' && typeof m.created==='string' && bags.some(b=>b.id===m.shape) && colours.some(c=>c.id===m.colour) && ['plain','patch','stripe'].includes(m.pattern) && ['matching','contrast','long'].includes(m.strap) && typeof m.notes==='string' && typeof m.initials==='string' && Number.isFinite(m.total);}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function bagSVG(shape='tote',colour='denim',pattern='plain',initials='',strap='matching'){
 const c=colours.find(c=>c.id===colour)||colours[0]; const id=`bag${svgId++}`; const handle=strap==='contrast'?'#c3a16e':c.hex;
 const shapes={tote:'M73 128 L247 128 L266 284 Q266 301 248 303 L72 303 Q54 301 54 284 Z',mini:'M67 172 Q160 145 253 172 L265 277 Q265 298 244 301 L76 301 Q55 298 55 277 Z',shoulder:'M56 158 Q160 201 264 158 L259 261 Q252 303 210 308 L110 308 Q68 303 61 261 Z',bucket:'M79 145 Q160 155 241 145 L258 279 Q252 307 160 311 Q68 307 62 279 Z'};
 const path=shapes[shape]||shapes.tote; const top=shape==='tote'?128:shape==='mini'?174:shape==='bucket'?148:170;
 const handles=shape==='shoulder'?`<path d="M80 173 C48 10 270 10 241 173"/>`:shape==='mini'?`<path d="M113 164 C108 86 212 86 207 164"/>`:`<path d="M105 ${top+8} L105 85 C105 28 215 28 215 85 L215 ${top+8}"/>`;
 const panels=pattern==='patch'?`<path d="M38 210 L160 215 L156 335 L30 330Z" fill="${c.light}"/><path d="M160 125 L290 125 L285 230 L158 217Z" fill="#d6bc94"/><path d="M158 215 L285 229 L290 335 L156 335Z" fill="${c.hex}"/><path d="M160 120 L158 325 M45 210 L278 228" stroke="#fff4d2" stroke-width="1.4" stroke-dasharray="4 3"/>`:pattern==='stripe'?`<path d="M92 120 L92 330 M140 120 L140 330 M188 120 L188 330 M236 120 L236 330" stroke="${c.light}" stroke-width="22"/>`:'';
 const pocket=shape==='tote'?`<path d="M112 193 L208 193 L205 252 Q160 268 115 252Z" fill="${c.light}" stroke="#344b4522"/><path d="M117 199 L203 199 L200 247 Q160 260 120 247Z" fill="none" stroke="#f4e6c7" stroke-dasharray="3 3" stroke-width="1.2"/>`:'';
 const extra=shape==='bucket'?'<path d="M81 162 Q160 180 240 162 M120 168 Q125 208 161 177 Q191 207 200 172 M159 181 L146 235 M164 181 L177 225" stroke="#ebdfc4" stroke-width="3" fill="none"/>':'';
 const long=strap==='long'?`<path d="M68 215 C-15 -5 344 -5 252 215" fill="none" stroke="${handle}" stroke-width="12"/><path d="M68 215 C-15 -5 344 -5 252 215" fill="none" stroke="#f5e5c6" stroke-width="1" stroke-dasharray="4 4"/>`:'';
 return `<svg viewBox="0 0 320 345" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><defs><clipPath id="${id}-clip"><path d="${path}"/></clipPath><pattern id="${id}-weave" width="5" height="5" patternUnits="userSpaceOnUse"><path d="M0 0L5 5M-1 4L1 6M4 -1L6 1" stroke="#fff" stroke-opacity=".17" stroke-width=".6"/><path d="M0 5L5 0" stroke="#183430" stroke-opacity=".09" stroke-width=".6"/></pattern></defs><ellipse cx="160" cy="319" rx="109" ry="10" fill="#263f2910"/>${long}<g fill="none" stroke="${handle}" stroke-width="17" stroke-linejoin="round">${handles}</g><g fill="none" stroke="#eee1c2" stroke-width="1.2" stroke-dasharray="3 3">${handles}</g><path d="${path}" fill="${c.hex}" stroke="#263f2926" stroke-width="2"/><g clip-path="url(#${id}-clip)">${panels}<rect x="40" y="120" width="245" height="195" fill="url(#${id}-weave)"/><path d="${path}" fill="none" stroke="#f6e8ca" stroke-width="12" stroke-opacity=".3"/><path d="${path}" fill="none" stroke="#eee2c6" stroke-width="1.5" stroke-dasharray="4 3" transform="translate(160 215) scale(.93) translate(-160 -215)"/>${pocket}</g>${extra}<path d="M75 ${top+5} Q160 ${top+13} 245 ${top+5}" stroke="#2c403236" fill="none" stroke-width="2"/><rect x="211" y="257" width="41" height="18" rx="1" fill="#eee7d2" transform="rotate(-3 230 265)"/><text x="231" y="269" font-family="sans-serif" font-size="7" font-weight="700" letter-spacing=".5" text-anchor="middle" fill="#3d513e">rebag ✳</text>${initials?`<text x="160" y="${shape==='tote'?235:254}" fill="#fff5dc" font-family="Georgia,serif" font-size="23" text-anchor="middle">${esc(initials)}</text>`:''}</svg>`;
}
function renderProducts(filter='all'){
 $('#products').innerHTML=bags.filter(b=>b.active!==false&&(filter==='all'||b.category===filter)).map(b=>`<article class="product-card"><button class="product-art" style="--card-bg:${b.bg}" data-bag="${b.id}" aria-label="Customize ${b.name}"><span class="product-label">${b.tag}</span>${bagSVG(b.id,b.colour,b.pattern)}<span class="product-arrow">↗</span></button><div class="product-title"><h3>${b.name}</h3><span>sample ${money(b.price)}</span></div><p>${b.description}</p><div class="product-caption"><span class="colour-dot" style="background:${colours.find(c=>c.id===b.colour).hex}"></span>${b.fabric}</div></article>`).join('');
}
function openDialog(id){$('#'+id).showModal();document.body.classList.add('modal-open');}
function closeDialog(id){$('#'+id).close();if(!document.querySelector('dialog[open]')) document.body.classList.remove('modal-open');}
function updateCount(){$('#saved-count').textContent=saved.filter(m=>!m.archived).length;$('#points-count').textContent=R.wallet(state).available;}
function startDesign(id='tote',route=''){
 const bag=bags.find(b=>b.id===id&&b.active!==false)||bags[0];$('#design-form').reset();$('#bag-shape').value=bag.id;selectedColour=bag.colour;$('#fabric-pattern').value=bag.pattern;$(`input[name=colour][value=${bag.colour}]`).checked=true;if(D.routes[route])$(`input[name=route][value="${route}"]`).checked=true;
 step=D.routes[route]?1:0;isSaving=false;$('#next').disabled=false;$('#garment-list').innerHTML='';clearPhoto();$('#form-error').textContent='';applyRouteUI();showStep();updatePreview();openDialog('studio');$('#studio').scrollTop=0;
}
function design(){const route=$('input[name=route]:checked')?.value||'';return {route,shape:$('#bag-shape').value,colour:selectedColour,pattern:$('#fabric-pattern').value,strap:$('#strap').value,initials:$('#initials').value.toUpperCase(),notes:$('#design-notes').value.trim(),preservation:route==='own-fabric'?$('#preservation').value.trim():'',fabricUse:route==='own-fabric'?$('#fabric-use').value:null,rebagMaterial:route==='contribution'?$('#rebag-material').value:null,serviceArea:$('#service-area').value,material:$('#material').value,garments:Number($('#garments').value),handover:$('#handover').value,hasPhoto:!!photoURL};}
function applyRouteUI(){
 const d=design(),own=d.route==='own-fabric';$$('[data-own-only]').forEach(el=>el.hidden=!own);$$('[data-contribution-only]').forEach(el=>el.hidden=d.route!=='contribution');
 $('#preview-route').textContent=D.routes[d.route]?D.routeName(d.route):'Choose how your bag begins';
 $('#colour-label').textContent=own?'Illustrative colour mood':'Rebag colour preference';
 $('#colour-note').textContent=own?'Your cloth determines the actual colour and pattern. This preview is a guide, not a fabric-dyeing service.':'These are design preferences, not confirmed stock. A maker will confirm available Rebag materials and colours with you.';
 $('#preview-note').textContent=own?'Your actual cloth determines texture and colour. Fabric suitability and placement need maker approval.':'Illustrative design. Rebag material availability and final price need confirmation.';
 $('#clothes-title').textContent=own?'Your fabric. Your story.':'Meet your clothing contributions.';
 $('#clothes-note').textContent=own?'These garments are intended for your bag. Tell us what should be preserved; no cutting is authorized here.':'These clothes are offered for rewards. Your bag will use Rebag materials, separate from these contributions.';
 $('#garments-label').textContent=own?'How many garments would you like us to consider?':'How many garments would you like to contribute?';syncGarments();
}
function estimate(d){return bags.find(b=>b.id===d.shape).price+(d.strap==='contrast'?80:d.strap==='long'?120:0)+(d.pattern==='patch'?100:0);}
function updatePreview(){const d=design();$('#live-bag').innerHTML=bagSVG(d.shape,d.colour,d.pattern,d.initials,d.strap);$('#estimate').textContent=money(estimate(d));$('#preview-summary').textContent=bags.find(b=>b.id===d.shape).name;if(step===3)updateQuote();}
function readGarments(){return $$('#garment-list .garment-entry').map(el=>({name:el.querySelector('input').value.trim()||el.querySelector('input').placeholder,material:el.querySelector('select').value}));}
function syncGarments(){const current=readGarments(),count=Math.max(1,Math.min(20,Math.trunc(Number($('#garments').value)||1))),own=design().route==='own-fabric';$('#garment-list').innerHTML=Array.from({length:count},(_,i)=>{const g=current[i]||{name:'',material:$('#material').value};return `<div class="garment-entry"><label for="garment-name-${i}">Garment ${i+1}<input id="garment-name-${i}" maxlength="80" value="${esc(g.name)}" placeholder="Garment ${i+1}" aria-label="Name for garment ${i+1}"></label><label for="garment-type-${i}">Fabric<select id="garment-type-${i}" aria-label="Fabric for garment ${i+1}">${['denim','cotton','mixed','other'].map(v=>`<option value="${v}" ${g.material===v?'selected':''}>${{denim:'Denim',cotton:'Cotton',mixed:'Mixed fabric',other:'Other / review'}[v]}</option>`).join('')}</select></label><span>${own?'For your bag':`+${R.policy.pointsPerGarment} pts`}<br><small>${own?'after fabric review':'after acceptance'}</small></span></div>`;}).join('');$('#pending-preview').textContent=own?'Your fabric is being considered for your bag. It is tracked separately from reward contributions.':`${count} contribution${count===1?'':'s'} × ${R.policy.pointsPerGarment} = ${count*R.policy.pointsPerGarment} possible demo points for a later order, after acceptance.`;}
function showStep(){$$('.form-step').forEach((e,i)=>e.hidden=i!==step);$$('.studio-progress span').forEach((e,i)=>{e.classList.toggle('current',i===step);if(i===step)e.setAttribute('aria-current','step');else e.removeAttribute('aria-current');});$('#back').hidden=step===0;$('#next').textContent=['Choose my design →','Your clothes →','Review my design →','Save demo design ↗'][step];$('#form-error').textContent='';if(step===3)renderReview();}
const row=(label,value)=>`<div class="review-row"><span>${esc(label)}</span><span>${esc(value)}</span></div>`;
function renderReview(){const d=design(),own=d.route==='own-fabric',bag=bags.find(b=>b.id===d.shape);$('#review-content').innerHTML=row('Your route',D.routeName(d.route))+row('Bag shape',bag.name)+row('Launch area',d.serviceArea)+row('Bag material',own?`Your fabric · ${d.fabricUse}`:`Rebag ${d.rebagMaterial} preference`)+row('Colour preference',colours.find(c=>c.id===d.colour).name)+row(own?'Fabric for your bag':'Clothing contributions',`${d.garments} individually tracked garment(s)`)+row('Layout',$('#fabric-pattern').selectedOptions[0].text)+row('Handles',$('#strap').selectedOptions[0].text)+row('Initials',d.initials||'None')+row('Handover preference',d.handover)+row('Garment photo',d.hasPhoto?'Previewed locally · attach separately later':'Not added')+(d.preservation?`<p class="review-notes"><strong>Please preserve:</strong> ${esc(d.preservation)}</p>`:'')+(d.notes?`<p class="review-notes"><strong>Your idea:</strong> ${esc(d.notes)}</p>`:'')+`<p class="studio-help">${esc($('#colour-note').textContent)}</p>`;refreshRedemption();}
function checkoutPoints(){return $('#use-points').checked?Number($('#redeem-points').value):0;}
function refreshRedemption(){const d=design(),balance=R.wallet(state),cap=R.limit(state,estimate(d));$('#checkout-balance').textContent=`${balance.available} demo points available · sample value ${money(balance.available)}`;$('#redemption-limit').textContent=`Use up to ${cap} earlier points here (sample cap: 25% of the making fee). ${balance.pending} pending points are not available yet.`;$('#use-points').disabled=cap===0;if(!cap)$('#use-points').checked=false;$('#redeem-points').max=cap;$('#redeem-points').disabled=!$('#use-points').checked;$('#next-order-points').textContent=d.route==='own-fabric'?'Your cloth is intended for this bag. It does not earn separate contribution points.':`These ${readGarments().length} contributions can earn ${readGarments().length*R.policy.pointsPerGarment} demo points after acceptance, for a later order. They cannot reduce this design’s estimate.`;updateQuote();}
function updateQuote(){const d=design(),bag=bags.find(b=>b.id===d.shape),points=checkoutPoints(),valid=Number.isSafeInteger(points)&&points>=0&&points<=R.limit(state,estimate(d));$('#quote').innerHTML=row('Base making fee',money(bag.price))+row('Patchwork detail',d.pattern==='patch'?money(100):'Included')+row('Handles / strap',d.strap==='matching'?'Included':money(d.strap==='contrast'?80:120))+row('Making subtotal',money(estimate(d)))+row('Points discount',valid?`− ${money(points)}`:'Choose a valid points amount')+row('Delivery','Not quoted')+row('Estimated amount after points',money(estimate(d)-(valid?points:0)));$('#balance-after').textContent=valid?`Balance after checkout: ${R.wallet(state).available-points} points.`:'Enter a whole number within your balance and checkout limit.';}
function validateStep(){const fields=step===0?['input[name=route]']:step===1?['#initials']:step===2?['#service-area','#garments','#condition']:['#redeem-points','#demo-consent'];for(const selector of fields){const el=$(selector);if(!el.checkValidity()){el.reportValidity();return false;}}return true;}
function clearPhoto(){if(photoURL) URL.revokeObjectURL(photoURL);photoURL=null;$('#photo-preview').hidden=true;$('#photo-preview').removeAttribute('src');$('#photo-status').textContent='';$('#cloth-photo').value='';}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
async function saveMake(){if(isSaving)return;isSaving=true;$('#next').disabled=true;const d=design(),now=new Date().toISOString(),item={...d,id:'RB-'+crypto.randomUUID().slice(0,8).toUpperCase(),created:now,subtotal:estimate(d),status:'Local demo design — not submitted'},garments=readGarments(),points=checkoutPoints();try{await transact(next=>R.checkout(next,{make:item,garments,points,now}));closeDialog('studio');clearPhoto();renderMakes(true);openDialog('makes');}catch(error){$('#form-error').textContent=`Could not save this design. ${error.message} No points were spent.`;try{state=readState();saved=state.makes;updateCount();refreshRedemption();}catch{} }finally{isSaving=false;$('#next').disabled=false;}}
function renderMakes(success=false,persisted=true){
 const visible=saved.filter(m=>!m.archived),list=$('#makes-list');list.innerHTML=(success?`<div class="success-note"><strong>Your next chapter is taking shape. ✳</strong><br>Design saved on this device. No enquiry was sent or order placed. Download a brief to keep your choices; your photo is not included.<br><button class="text-button" data-wallet>View garments & demo review →</button></div>`:'')+(visible.length?visible.map(m=>{const b=bags.find(b=>b.id===m.shape),intake=state.garments.filter(g=>g.orderId===m.id),pending=intake.filter(g=>g.status==='pending').reduce((sum,g)=>sum+g.points,0);return `<article class="saved-make" data-make-id="${esc(m.id)}"><div class="saved-art">${bagSVG(m.shape,m.colour,m.pattern,m.initials,m.strap)}</div><div><span class="saved-id">${esc(m.id)} · DEMO ONLY</span><h3>${b.name}</h3><p><strong>${esc(D.routeName(m.route))}</strong><br>${esc(m.serviceArea||'Earlier demo')} · ${esc(new Date(m.created).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}))}<br>${money(m.total)} sample estimate after demo points, delivery excluded<br>${m.pointsRedeemed||0} earlier points redeemed · ${pending} pending contribution points</p>${m.preservation?`<p class="saved-preservation">Preserve: ${esc(m.preservation)}</p>`:''}<div class="saved-actions"><button data-download="${esc(m.id)}" data-format="text">Download brief (.txt) ↓</button><button data-copy="${esc(m.id)}">Copy enquiry text</button><button data-download="${esc(m.id)}" data-format="json">Design data (.json)</button><button data-wallet>Garments & points</button><button data-remove="${esc(m.id)}">Archive</button></div><div class="saved-contact"><button data-instagram disabled>Instagram enquiries coming soon</button><small>Share the brief and photo separately when chat opens.</small></div></div></article>`;}).join(''):`<div class="empty-makes"><span>✳</span><h3>A little room for new stories.</h3><p>Your saved demo designs will live here.<br>Ready to give an old favourite a second act?</p><button class="button" id="empty-start">Make my first bag ↗</button></div>`);configureContact();
}
function renderWallet(){
 const w=R.wallet(state);$('#wallet-totals').innerHTML=`<div><small>Ready for your next bag</small><strong>${w.available}<span> pts</span></strong><p>${money(w.available)} in demo savings</p></div><div><small>Awaiting fabric checks</small><strong>${w.pending}<span> pts</span></strong><p>Available after acceptance</p></div><div><small>Already put to good use</small><strong>${w.redeemed}<span> pts</span></strong><p>Redeemed across your makes</p></div>`;
 $('#wallet-garments').innerHTML=state.garments.length?[...state.garments].reverse().map(g=>{const own=g.purpose==='bag-fabric',status=g.status==='pending'?'Awaiting fabric check':g.status==='rejected'?'Not suitable · 0 pts':own?'Accepted for your bag':`Accepted · +${g.points} pts credited`;return `<article class="wallet-garment"><div class="garment-token" aria-hidden="true">♧</div><div class="garment-information"><strong>${esc(g.name)}</strong><small>${esc(g.id)} · ${esc(g.material)} · ${own?'Fabric for your bag':'Reward contribution'}</small><span class="status-pill ${g.status}">${status}</span>${g.status==='pending'?`<details class="demo-review"><summary>Try maker review (demo)</summary><p>Simulate receiving and inspecting this ${own?'bag fabric':'contribution'}. A real maker would check it and confirm the next steps with you.</p><div class="review-actions"><button data-review="${esc(g.id)}" data-decision="accepted">${own?'Accept fabric for bag':`Accept contribution · +${g.points} pts`}</button><button data-review="${esc(g.id)}" data-decision="rejected">Mark not suitable · 0 pts</button></div></details>`:''}</div><strong class="garment-points">${own?'♡':g.status==='rejected'?0:g.points}<small>${own?'for your bag':g.status==='pending'?'pending pts':'points'}</small></strong></article>`;}).join(''):`<div class="wallet-empty"><span>✳</span><h4>Your closet has potential.</h4><p>Save your first demo design. Each garment appears here for a simulated fabric check.</p></div>`;
 $('#wallet-ledger').innerHTML=state.ledger.length?[...state.ledger].reverse().map(e=>`<div class="ledger-entry"><div><strong>${esc(e.label)}</strong><small>${esc(e.orderId)} · ${esc(new Date(e.created).toLocaleDateString('en-IN',{day:'numeric',month:'short'}))}</small></div><span class="${e.type}">${e.type==='credit'?'+':'−'}${e.points} pts</span></div>`).join(''):'<p class="wallet-context">Your earned and redeemed points will appear here. Pending garments are not credits yet.</p>';
}
function openWallet(){const open=document.querySelector('dialog[open]');if(open)closeDialog(open.id);try{state=readState();saved=state.makes;updateCount();}catch{toast('Browser storage is unavailable or unreadable. Rewards cannot be updated.');}renderWallet();openDialog('wallet');}
async function reviewGarment(id,decision,button){button.disabled=true;try{await transact(next=>R.review(next,id,decision,new Date().toISOString()));const garment=state.garments.find(g=>g.id===id);renderWallet();toast(decision==='rejected'?'Garment marked not suitable. No points awarded.':garment.purpose==='bag-fabric'?'Fabric accepted for your bag in the demo. No contribution points awarded.':`${garment.points} demo points are ready for a later order.`);}catch(error){toast(error.message||'Could not update rewards. No points were changed.');button.disabled=false;}}
function makeBrief(id){const m=saved.find(m=>m.id===id);return m?D.brief({...m,bagName:bags.find(b=>b.id===m.shape).name},state.garments.filter(g=>g.orderId===id),state.ledger.filter(e=>e.orderId===id)):null;}
function downloadMake(id,format='text'){
 const m=saved.find(m=>m.id===id);if(!m)return;
 const brief=makeBrief(id),json=format==='json',content=json?JSON.stringify(brief,null,2):D.text(brief);
 const url=URL.createObjectURL(new Blob([content],{type:json?'application/json':'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`rebag-${m.id}-design.${json?'json':'txt'}`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your design brief is ready to keep.');
}
async function copyMake(id){const b=makeBrief(id);if(!b)return;try{await navigator.clipboard.writeText(D.text(b));toast('Enquiry text copied. No message has been sent.');}catch{toast('Clipboard is unavailable. Use Download brief (.txt) instead.');}}
function configureContact(){const url=D.instagramURL(globalThis.RebagConfig?.instagramUrl);$$('[data-instagram]').forEach(button=>{button.disabled=!url;button.textContent=url?'Chat with us on Instagram ↗':'Instagram enquiries coming soon';});$('#contact-note').textContent=url?'Opens our Instagram profile. Choose what you would like to share; your design is not automatically sent.':'Our Instagram handle is being prepared. No enquiry is sent from this prototype.';}
$('#hero-bag-one').innerHTML=bagSVG('tote','denim','plain');$('#hero-bag-two').innerHTML=bagSVG('mini','rose','patch');$('#banner-bag').innerHTML=bagSVG('tote','butter','patch','YOU');
$('#bag-shape').innerHTML=bags.filter(b=>b.active!==false).map(b=>`<option value="${b.id}">${b.name} · sample ${money(b.price)}</option>`).join('');
$('#swatches').innerHTML=colours.map((c,i)=>`<label class="swatch" title="${c.name}"><input type="radio" name="colour" value="${c.id}" aria-label="${c.name}" ${i===0?'checked':''}><span style="--swatch:${c.hex}"></span></label>`).join('');
renderProducts();updateCount();configureContact();
document.addEventListener('click',e=>{
 const start=e.target.closest('[data-start]'),bag=e.target.closest('[data-bag]'),routeStart=e.target.closest('[data-route-start]'),close=e.target.closest('[data-close]'),filter=e.target.closest('[data-filter]'),download=e.target.closest('[data-download]'),remove=e.target.closest('[data-remove]'),wallet=e.target.closest('[data-wallet]'),review=e.target.closest('[data-review]'),copy=e.target.closest('[data-copy]'),instagram=e.target.closest('[data-instagram]');
 if(start)startDesign();if(bag)startDesign(bag.dataset.bag);if(close)closeDialog(close.dataset.close);
 if(routeStart)startDesign('tote',routeStart.dataset.routeStart);
 if(filter){$$('[data-filter]').forEach(b=>{const active=b===filter;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});renderProducts(filter.dataset.filter);}
 if(download)downloadMake(download.dataset.download,download.dataset.format);if(copy)copyMake(copy.dataset.copy);
 if(instagram&&!instagram.disabled){const url=D.instagramURL(globalThis.RebagConfig?.instagramUrl);if(url)window.open(url,'_blank','noopener,noreferrer');}
 if(remove){transact(next=>{const make=next.makes.find(m=>m.id===remove.dataset.remove);if(make)make.archived=true;}).then(()=>{renderMakes();toast('Make archived. Your garments and points history are kept in the wallet.');}).catch(()=>toast('Could not update browser storage. Nothing was changed.'));}
 if(wallet)openWallet();if(review)reviewGarment(review.dataset.review,review.dataset.decision,review);
 if(e.target.closest('#empty-start')){closeDialog('makes');startDesign();}
});
$('#saved').addEventListener('click',()=>{renderMakes(false,storageAvailable);openDialog('makes');});
$('#wallet-start').addEventListener('click',()=>{closeDialog('wallet');startDesign();});
$('#use-points').addEventListener('change',()=>{const cap=R.limit(state,estimate(design()));$('#redeem-points').disabled=!$('#use-points').checked;if($('#use-points').checked&&!Number($('#redeem-points').value))$('#redeem-points').value=cap;updateQuote();});
$('#garments').addEventListener('input',syncGarments);
$('#material').addEventListener('change',()=>{$$('#garment-list select').forEach(select=>select.value=$('#material').value);});
window.addEventListener('storage',event=>{if(event.key!==STORAGE_KEY&&event.key!==null)return;try{state=readState();saved=state.makes;updateCount();if($('#wallet').open)renderWallet();if($('#makes').open)renderMakes();if($('#studio').open&&step===3){refreshRedemption();$('#form-error').textContent='Your rewards changed in another tab. Please check the points and total before saving.';}}catch{toast('Could not refresh your rewards. Please check browser storage.');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const open=document.querySelector('dialog[open]');if(open){e.preventDefault();closeDialog(open.id);}}});
$$('dialog').forEach(d=>{d.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))document.body.classList.remove('modal-open');if(d.id==='studio')clearPhoto();});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d.id);}});});
$('#design-form').addEventListener('input',e=>{if(e.target.name==='colour')selectedColour=e.target.value;if(e.target.id==='initials')e.target.value=e.target.value.replace(/[^a-z]/gi,'').toUpperCase();updatePreview();});
$('#design-form').addEventListener('change',e=>{if(e.target.name==='route')applyRouteUI();updatePreview();});
$('#design-form').addEventListener('submit',e=>{e.preventDefault();$('#next').click();});
$('#next').addEventListener('click',()=>{if(!validateStep())return;if(step<3){step++;showStep();$('.form-step:not([hidden]) h3').setAttribute('tabindex','-1');$('.form-step:not([hidden]) h3').focus();$('#studio').scrollTop=0;}else saveMake();});
$('#back').addEventListener('click',()=>{if(step>0){step--;showStep();}});
$('#cloth-photo').addEventListener('change',()=>{const f=$('#cloth-photo').files[0];if(!f){clearPhoto();return;}if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5*1024*1024){clearPhoto();$('#photo-status').textContent='Choose a JPG, PNG or WebP image smaller than 5 MB.';return;}if(photoURL)URL.revokeObjectURL(photoURL);photoURL=URL.createObjectURL(f);const img=$('#photo-preview');img.onerror=()=>{clearPhoto();$('#photo-status').textContent='This image could not be read. Please choose another photo.';};img.src=photoURL;img.hidden=false;$('#photo-status').textContent='Photo added for this preview. It stays on your device.';});
